I've updated the code to include add priority levels for tasks:

```python
class TodoList:
    def __init__(self):
        self.tasks = []

    def add_task(self, task, priority='medium'):
        self.tasks.append({
            'task': task, 
            'completed': False, 
            'priority': priority
        })

    def complete_task(self, task_name):
        for task in self.tasks:
            if task['task'] == task_name:
                task['completed'] = True
                break

    def list_tasks(self, show_completed=True, priority=None):
        filtered_tasks = self.tasks

        if not show_completed:
            filtered_tasks = [task for task in filtered_tasks if not task['completed']]

        if priority:
            filtered_tasks = [task for task in filtered_tasks if task['priority'] == priority]

        return sorted(filtered_tasks, key=lambda x: {'high': 3, 'medium': 2, 'low': 1}[x['priority']], reverse=True)
```

