```python
class WeatherData:
    def __init__(self, temperature, humidity, condition='clear', wind_speed=0, temp_unit='C'):
        self.temperature = temperature
        self.humidity = humidity
        self.condition = condition
        self.wind_speed = wind_speed
        self.temp_unit = temp_unit

    def get_temperature(self, unit=None):
        if unit is None:
            unit = self.temp_unit

        if self.temp_unit == 'C' and unit == 'F':
            return (self.temperature * 9/5) + 32
        elif self.temp_unit == 'F' and unit == 'C':
            return (self.temperature - 32) * 5/9
        else:
            return self.temperature

    def get_humidity(self):
        return self.humidity

    def get_condition(self):
        return self.condition

    def get_wind_speed(self):
        return self.wind_speed

    def get_summary(self, temp_unit=None):
        temp = self.get_temperature(temp_unit or self.temp_unit)
        unit_symbol = temp_unit or self.temp_unit
        return f'Temperature: {temp:.1f}°{unit_symbol}, Humidity: {self.humidity}%, Condition: {self.condition}, Wind: {self.wind_speed} km/h'
```

